"""Lexer for the microvm language."""

import dataclasses

from .errors import LexError

KEYWORDS: frozenset[str] = frozenset(
    {"let", "print", "if", "else", "while", "true", "false", "and", "or", "not"}
)

# Longest match wins: two-char operators must be listed before their one-char prefix.
OPERATORS: tuple[str, ...] = (
    "==", "!=", "<=", ">=",
    "+", "-", "*", "/", "%", "(", ")", "{", "}", ";", "=", "<", ">",
)


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str
    text: str
    value: object
    offset: int


def _is_ident_start(ch: str) -> bool:
    return ch.isalpha() or ch == "_"


def _is_ident_part(ch: str) -> bool:
    return ch.isalnum() or ch == "_"


def _lex_number(src: str, i: int) -> tuple["Token", int]:
    start = i
    n = len(src)
    while i < n and src[i].isdigit():
        i += 1
    is_float = False
    if i < n and src[i] == ".":
        if i + 1 < n and src[i + 1].isdigit():
            is_float = True
            i += 1
            while i < n and src[i].isdigit():
                i += 1
        else:
            raise LexError("malformed float literal", start)
    if i < n and src[i] in "eE":
        j = i + 1
        if j < n and src[j] in "+-":
            j += 1
        if j < n and src[j].isdigit():
            is_float = True
            i = j
            while i < n and src[i].isdigit():
                i += 1
        else:
            raise LexError("malformed exponent", start)
    text = src[start:i]
    if is_float:
        return Token("FLOAT", text, float(text), start), i
    return Token("INT", text, int(text), start), i


def _lex_string(src: str, i: int) -> tuple["Token", int]:
    start = i
    n = len(src)
    i += 1
    out: list[str] = []
    escapes = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}
    while True:
        if i >= n:
            raise LexError("unterminated string", start)
        ch = src[i]
        if ch == "\n":
            raise LexError("unterminated string", start)
        if ch == '"':
            i += 1
            break
        if ch == "\\":
            if i + 1 >= n or src[i + 1] not in escapes:
                raise LexError("invalid escape sequence", i)
            out.append(escapes[src[i + 1]])
            i += 2
            continue
        out.append(ch)
        i += 1
    value = "".join(out)
    return Token("STRING", value, value, start), i


def tokenize(src: str) -> list[Token]:
    tokens: list[Token] = []
    i = 0
    n = len(src)
    while i < n:
        ch = src[i]
        if ch in " \t\r\n":
            i += 1
            continue
        if ch == "/" and i + 1 < n and src[i + 1] == "/":
            while i < n and src[i] != "\n":
                i += 1
            continue
        if ch.isdigit():
            tok, i = _lex_number(src, i)
            tokens.append(tok)
            continue
        if ch == '"':
            tok, i = _lex_string(src, i)
            tokens.append(tok)
            continue
        if _is_ident_start(ch):
            start = i
            i += 1
            while i < n and _is_ident_part(src[i]):
                i += 1
            text = src[start:i]
            if text in KEYWORDS:
                tokens.append(Token("KEYWORD", text, text, start))
            else:
                tokens.append(Token("IDENT", text, text, start))
            continue
        matched = None
        for op in OPERATORS:
            if src.startswith(op, i):
                matched = op
                break
        if matched is None:
            raise LexError(f"unexpected character {ch!r}", i)
        tokens.append(Token("OP", matched, matched, i))
        i += len(matched)
    return tokens

"""Recursive-descent parser for the microvm language."""

import dataclasses

from .errors import ParseError
from .lexer import Token, tokenize


# ---------------------------------------------------------------------------
# AST node definitions. The shape is internal; only parse()'s error behaviour
# is part of the observable contract.
# ---------------------------------------------------------------------------

@dataclasses.dataclass
class Module:
    body: list


@dataclasses.dataclass
class LetStmt:
    name: str
    expr: object
    offset: int


@dataclasses.dataclass
class AssignStmt:
    name: str
    expr: object
    offset: int


@dataclasses.dataclass
class PrintStmt:
    expr: object


@dataclasses.dataclass
class IfStmt:
    cond: object
    then_body: list
    else_body: list | None


@dataclasses.dataclass
class WhileStmt:
    cond: object
    body: list


@dataclasses.dataclass
class IntLit:
    value: int


@dataclasses.dataclass
class FloatLit:
    value: float


@dataclasses.dataclass
class StrLit:
    value: str


@dataclasses.dataclass
class BoolLit:
    value: bool


@dataclasses.dataclass
class VarRef:
    name: str
    offset: int


@dataclasses.dataclass
class Neg:
    expr: object


@dataclasses.dataclass
class NotOp:
    expr: object


@dataclasses.dataclass
class BinOp:
    op: str
    left: object
    right: object
    offset: int


@dataclasses.dataclass
class LogicOp:
    op: str
    left: object
    right: object


class _Parser:
    def __init__(self, tokens: list[Token], src_len: int) -> None:
        self.tokens = tokens
        self.pos = 0
        self.src_len = src_len

    def _offset(self) -> int:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos].offset
        return self.src_len

    def _peek(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _advance(self) -> Token:
        tok = self._peek()
        if tok is None:
            raise ParseError("unexpected end of input", self.src_len)
        self.pos += 1
        return tok

    def _check_kw(self, kw: str) -> bool:
        tok = self._peek()
        return tok is not None and tok.kind == "KEYWORD" and tok.text == kw

    def _check_op(self, op: str) -> bool:
        tok = self._peek()
        return tok is not None and tok.kind == "OP" and tok.text == op

    def _expect_op(self, op: str) -> Token:
        if not self._check_op(op):
            raise ParseError(f"expected {op!r}", self._offset())
        return self._advance()

    def _expect_kw(self, kw: str) -> Token:
        if not self._check_kw(kw):
            raise ParseError(f"expected {kw!r}", self._offset())
        return self._advance()

    def parse_module(self) -> Module:
        body = []
        while self._peek() is not None:
            body.append(self.parse_stmt())
        return Module(body)

    def parse_stmt(self) -> object:
        if self._check_kw("let"):
            return self._parse_let()
        if self._check_kw("print"):
            return self._parse_print()
        if self._check_kw("if"):
            return self._parse_if()
        if self._check_kw("while"):
            return self._parse_while()
        if self._check_op("{"):
            return Module(self._parse_block())
        return self._parse_assign()

    def _parse_let(self) -> LetStmt:
        offset = self._advance().offset
        name_tok = self._peek()
        if name_tok is None or name_tok.kind != "IDENT":
            raise ParseError("expected identifier after 'let'", self._offset())
        self._advance()
        self._expect_op("=")
        expr = self.parse_expr()
        self._expect_op(";")
        return LetStmt(name_tok.text, expr, offset)

    def _parse_assign(self) -> AssignStmt:
        name_tok = self._peek()
        if name_tok is None or name_tok.kind != "IDENT":
            raise ParseError("expected statement", self._offset())
        offset = name_tok.offset
        self._advance()
        self._expect_op("=")
        expr = self.parse_expr()
        self._expect_op(";")
        return AssignStmt(name_tok.text, expr, offset)

    def _parse_print(self) -> PrintStmt:
        self._advance()
        expr = self.parse_expr()
        self._expect_op(";")
        return PrintStmt(expr)

    def _parse_block(self) -> list:
        self._expect_op("{")
        stmts = []
        while not self._check_op("}"):
            if self._peek() is None:
                raise ParseError("unterminated block", self._offset())
            stmts.append(self.parse_stmt())
        self._advance()
        return stmts

    def _parse_if(self) -> IfStmt:
        self._advance()
        self._expect_op("(")
        cond = self.parse_expr()
        self._expect_op(")")
        then_body = self._parse_block()
        else_body = None
        if self._check_kw("else"):
            self._advance()
            if self._check_kw("if"):
                else_body = [self._parse_if()]
            else:
                else_body = self._parse_block()
        return IfStmt(cond, then_body, else_body)

    def _parse_while(self) -> WhileStmt:
        self._advance()
        self._expect_op("(")
        cond = self.parse_expr()
        self._expect_op(")")
        body = self._parse_block()
        return WhileStmt(cond, body)

    # -- expressions --------------------------------------------------

    def parse_expr(self) -> object:
        return self._parse_or()

    def _parse_or(self) -> object:
        left = self._parse_and()
        while self._check_kw("or"):
            self._advance()
            right = self._parse_and()
            left = LogicOp("or", left, right)
        return left

    def _parse_and(self) -> object:
        left = self._parse_not()
        while self._check_kw("and"):
            self._advance()
            right = self._parse_not()
            left = LogicOp("and", left, right)
        return left

    def _parse_not(self) -> object:
        if self._check_kw("not"):
            self._advance()
            return NotOp(self._parse_not())
        return self._parse_comparison()

    _COMPARE_OPS = ("==", "!=", "<=", ">=", "<", ">")

    def _parse_comparison(self) -> object:
        left = self._parse_additive()
        tok = self._peek()
        if tok is not None and tok.kind == "OP" and tok.text in self._COMPARE_OPS:
            op = tok.text
            offset = tok.offset
            self._advance()
            right = self._parse_additive()
            left = BinOp(op, left, right, offset)
            tok2 = self._peek()
            if tok2 is not None and tok2.kind == "OP" and tok2.text in self._COMPARE_OPS:
                raise ParseError("comparison is not associative", tok2.offset)
        return left

    def _parse_additive(self) -> object:
        left = self._parse_multiplicative()
        while True:
            tok = self._peek()
            if tok is not None and tok.kind == "OP" and tok.text in ("+", "-"):
                self._advance()
                right = self._parse_multiplicative()
                left = BinOp(tok.text, left, right, tok.offset)
            else:
                break
        return left

    def _parse_multiplicative(self) -> object:
        left = self._parse_unary()
        while True:
            tok = self._peek()
            if tok is not None and tok.kind == "OP" and tok.text in ("*", "/", "%"):
                self._advance()
                right = self._parse_unary()
                left = BinOp(tok.text, left, right, tok.offset)
            else:
                break
        return left

    def _parse_unary(self) -> object:
        if self._check_op("-"):
            self._advance()
            return Neg(self._parse_unary())
        return self._parse_primary()

    def _parse_primary(self) -> object:
        tok = self._peek()
        if tok is None:
            raise ParseError("unexpected end of input", self.src_len)
        if tok.kind == "INT":
            self._advance()
            return IntLit(tok.value)
        if tok.kind == "FLOAT":
            self._advance()
            return FloatLit(tok.value)
        if tok.kind == "STRING":
            self._advance()
            return StrLit(tok.value)
        if tok.kind == "KEYWORD" and tok.text == "true":
            self._advance()
            return BoolLit(True)
        if tok.kind == "KEYWORD" and tok.text == "false":
            self._advance()
            return BoolLit(False)
        if tok.kind == "IDENT":
            self._advance()
            return VarRef(tok.text, tok.offset)
        if tok.kind == "OP" and tok.text == "(":
            self._advance()
            expr = self.parse_expr()
            self._expect_op(")")
            return expr
        raise ParseError("expected expression", tok.offset)


def parse(src: str) -> object:
    tokens = tokenize(src)
    parser = _Parser(tokens, len(src))
    module = parser.parse_module()
    if parser.pos != len(tokens):
        raise ParseError("trailing tokens", parser._offset())
    return module

"""Bytecode compiler: AST -> Program."""

import dataclasses

from .errors import CompileError
from .opcodes import OPCODES
from .optimizer import fold_constants
from .parser import (
    AssignStmt,
    BinOp,
    BoolLit,
    FloatLit,
    IfStmt,
    IntLit,
    LetStmt,
    LogicOp,
    Module,
    Neg,
    NotOp,
    PrintStmt,
    StrLit,
    VarRef,
    WhileStmt,
    parse,
)


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str
    arg: int | None


@dataclasses.dataclass
class Program:
    constants: list
    names: list[str]
    instructions: list


_BINOP_TO_OPCODE: dict[str, str] = {
    "+": "ADD", "-": "SUB", "*": "MUL", "/": "DIV", "%": "MOD",
    "==": "EQ", "!=": "NE", "<": "LT", "<=": "LE", ">": "GT", ">=": "GE",
}


def _collect_names(stmts: list, names: list[str], slots: dict[str, int]) -> None:
    for stmt in stmts:
        if isinstance(stmt, LetStmt):
            if stmt.name in slots:
                raise CompileError(f"variable {stmt.name!r} already declared")
            slots[stmt.name] = len(names)
            names.append(stmt.name)
        elif isinstance(stmt, Module):
            _collect_names(stmt.body, names, slots)
        elif isinstance(stmt, IfStmt):
            _collect_names(stmt.then_body, names, slots)
            if stmt.else_body is not None:
                _collect_names(stmt.else_body, names, slots)
        elif isinstance(stmt, WhileStmt):
            _collect_names(stmt.body, names, slots)


def _check_names_stmts(stmts: list, slots: dict[str, int]) -> None:
    for stmt in stmts:
        if isinstance(stmt, LetStmt):
            _check_names_expr(stmt.expr, slots)
        elif isinstance(stmt, AssignStmt):
            if stmt.name not in slots:
                raise CompileError(f"assignment to undeclared variable {stmt.name!r}")
            _check_names_expr(stmt.expr, slots)
        elif isinstance(stmt, PrintStmt):
            _check_names_expr(stmt.expr, slots)
        elif isinstance(stmt, Module):
            _check_names_stmts(stmt.body, slots)
        elif isinstance(stmt, IfStmt):
            _check_names_expr(stmt.cond, slots)
            _check_names_stmts(stmt.then_body, slots)
            if stmt.else_body is not None:
                _check_names_stmts(stmt.else_body, slots)
        elif isinstance(stmt, WhileStmt):
            _check_names_expr(stmt.cond, slots)
            _check_names_stmts(stmt.body, slots)


def _check_names_expr(node: object, slots: dict[str, int]) -> None:
    if isinstance(node, VarRef):
        if node.name not in slots:
            raise CompileError(f"use of undeclared variable {node.name!r}")
    elif isinstance(node, (Neg, NotOp)):
        _check_names_expr(node.expr, slots)
    elif isinstance(node, (BinOp, LogicOp)):
        _check_names_expr(node.left, slots)
        _check_names_expr(node.right, slots)


class _CodeGen:
    def __init__(self, slots: dict[str, int]) -> None:
        self.slots = slots
        self.instructions: list[Instr] = []
        self.const_index: dict[tuple, int] = {}
        self.constants: list = []

    def emit(self, op: str, arg: int | None = None) -> int:
        self.instructions.append(Instr(op, arg))
        return len(self.instructions) - 1

    def patch(self, index: int, target: int) -> None:
        self.instructions[index] = Instr(self.instructions[index].op, target)

    def here(self) -> int:
        return len(self.instructions)

    def const_id(self, value: object) -> int:
        key = (type(value), value)
        if key in self.const_index:
            return self.const_index[key]
        idx = len(self.constants)
        self.constants.append(value)
        self.const_index[key] = idx
        return idx

    def compile_stmts(self, stmts: list) -> None:
        for stmt in stmts:
            self.compile_stmt(stmt)

    def compile_stmt(self, stmt: object) -> None:
        if isinstance(stmt, Module):
            self.compile_stmts(stmt.body)
        elif isinstance(stmt, LetStmt):
            self.compile_expr(stmt.expr)
            self.emit("STORE", self.slots[stmt.name])
        elif isinstance(stmt, AssignStmt):
            self.compile_expr(stmt.expr)
            self.emit("STORE", self.slots[stmt.name])
        elif isinstance(stmt, PrintStmt):
            self.compile_expr(stmt.expr)
            self.emit("PRINT")
        elif isinstance(stmt, IfStmt):
            self._compile_if(stmt)
        elif isinstance(stmt, WhileStmt):
            self._compile_while(stmt)

    def _compile_if(self, stmt: IfStmt) -> None:
        self.compile_expr(stmt.cond)
        jf = self.emit("JUMP_IF_FALSE")
        self.compile_stmts(stmt.then_body)
        if stmt.else_body is not None:
            jend = self.emit("JUMP")
            self.patch(jf, self.here())
            self.compile_stmts(stmt.else_body)
            self.patch(jend, self.here())
        else:
            self.patch(jf, self.here())

    def _compile_while(self, stmt: WhileStmt) -> None:
        start = self.here()
        self.compile_expr(stmt.cond)
        jf = self.emit("JUMP_IF_FALSE")
        self.compile_stmts(stmt.body)
        self.emit("JUMP", start)
        self.patch(jf, self.here())

    def compile_expr(self, node: object) -> None:
        if isinstance(node, IntLit):
            self.emit("CONST", self.const_id(node.value))
        elif isinstance(node, FloatLit):
            self.emit("CONST", self.const_id(node.value))
        elif isinstance(node, StrLit):
            self.emit("CONST", self.const_id(node.value))
        elif isinstance(node, BoolLit):
            self.emit("CONST", self.const_id(node.value))
        elif isinstance(node, VarRef):
            self.emit("LOAD", self.slots[node.name])
        elif isinstance(node, Neg):
            self.compile_expr(node.expr)
            self.emit("NEG")
        elif isinstance(node, NotOp):
            self.compile_expr(node.expr)
            self.emit("NOT")
        elif isinstance(node, BinOp):
            self.compile_expr(node.left)
            self.compile_expr(node.right)
            self.emit(_BINOP_TO_OPCODE[node.op])
        elif isinstance(node, LogicOp):
            self._compile_logic(node)

    def _compile_logic(self, node: LogicOp) -> None:
        self.compile_expr(node.left)
        jf = self.emit("JUMP_IF_FALSE")
        if node.op == "and":
            self.compile_expr(node.right)
            self.emit("NOT")
            self.emit("NOT")
            jend = self.emit("JUMP")
            self.patch(jf, self.here())
            self.emit("CONST", self.const_id(False))
            self.patch(jend, self.here())
        else:
            self.emit("CONST", self.const_id(True))
            jend = self.emit("JUMP")
            self.patch(jf, self.here())
            self.compile_expr(node.right)
            self.emit("NOT")
            self.emit("NOT")
            self.patch(jend, self.here())


def compile_source(src: str, *, optimize: bool = False) -> Program:
    module = parse(src)
    names: list[str] = []
    slots: dict[str, int] = {}
    _collect_names(module.body, names, slots)
    _check_names_stmts(module.body, slots)
    if optimize:
        module = fold_constants(module)
    gen = _CodeGen(slots)
    gen.compile_stmts(module.body)
    gen.emit("HALT")
    assert all(op in OPCODES for op in (i.op for i in gen.instructions))
    return Program(gen.constants, names, gen.instructions)

"""Stack virtual machine for microvm bytecode."""

from typing import TYPE_CHECKING

from .errors import StepLimitError, VMRuntimeError

if TYPE_CHECKING:
    from .compiler import Program

_UNSET = object()


def _is_bool(v: object) -> bool:
    return type(v) is bool


def _is_number(v: object) -> bool:
    return isinstance(v, (int, float)) and not _is_bool(v)


def _values_equal(left: object, right: object) -> bool:
    if _is_bool(left) or _is_bool(right):
        return _is_bool(left) and _is_bool(right) and left == right
    if _is_number(left) and _is_number(right):
        return left == right
    if isinstance(left, str) and isinstance(right, str):
        return left == right
    return False


def _apply_additive_like(op: str, left: object, right: object) -> object:
    if op == "+" and isinstance(left, str) and isinstance(right, str):
        return left + right
    if not (_is_number(left) and _is_number(right)):
        raise VMRuntimeError(f"operator {op!r} requires two numbers (or two strings for +)")
    if op == "+":
        result = left + right
    elif op == "-":
        result = left - right
    else:
        result = left * right
    if isinstance(left, float) or isinstance(right, float):
        return float(result)
    return int(result)


def _apply_div(left: object, right: object) -> float:
    if not (_is_number(left) and _is_number(right)):
        raise VMRuntimeError("operator '/' requires two numbers")
    if right == 0:
        raise VMRuntimeError("division by zero")
    return left / right


def _apply_mod(left: object, right: object) -> int:
    if not (type(left) is int and type(right) is int):
        raise VMRuntimeError("operator '%' requires two integers")
    if right == 0:
        raise VMRuntimeError("modulo by zero")
    return left % right


def _apply_order(op: str, left: object, right: object) -> bool:
    if _is_number(left) and _is_number(right):
        pass
    elif isinstance(left, str) and isinstance(right, str):
        pass
    else:
        raise VMRuntimeError(f"operator {op!r} requires two numbers or two strings")
    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    if op == ">":
        return left > right
    return left >= right


def apply_binary(op: str, left: object, right: object) -> object:
    """Apply a binary operator's runtime semantics; shared by the VM and the optimizer."""
    if op in ("+", "-", "*"):
        return _apply_additive_like(op, left, right)
    if op == "/":
        return _apply_div(left, right)
    if op == "%":
        return _apply_mod(left, right)
    if op == "==":
        return _values_equal(left, right)
    if op == "!=":
        return not _values_equal(left, right)
    return _apply_order(op, left, right)


def apply_neg(value: object) -> object:
    if not _is_number(value):
        raise VMRuntimeError("unary '-' requires a number")
    return -value


def apply_not(value: object) -> bool:
    if not _is_bool(value):
        raise VMRuntimeError("'not' requires a bool")
    return not value


def render(value: object) -> str:
    if _is_bool(value):
        return "true" if value else "false"
    return str(value)


_BINOP_OPCODES = frozenset({"ADD", "SUB", "MUL", "DIV", "MOD", "EQ", "NE", "LT", "LE", "GT", "GE"})
_BINOP_SYMBOL = {
    "ADD": "+", "SUB": "-", "MUL": "*", "DIV": "/", "MOD": "%",
    "EQ": "==", "NE": "!=", "LT": "<", "LE": "<=", "GT": ">", "GE": ">=",
}


def _run_binop(op: str, stack: list) -> None:
    right = stack.pop()
    left = stack.pop()
    stack.append(apply_binary(_BINOP_SYMBOL[op], left, right))


def _exec_instr(instr: object, ip: int, ctx: dict) -> int:
    op = instr.op
    stack: list = ctx["stack"]
    if op == "CONST":
        stack.append(ctx["constants"][instr.arg])
    elif op == "LOAD":
        value = ctx["vars"][instr.arg]
        if value is _UNSET:
            raise VMRuntimeError(f"variable {ctx['names'][instr.arg]!r} used before assignment")
        stack.append(value)
    elif op == "STORE":
        ctx["vars"][instr.arg] = stack.pop()
    elif op in _BINOP_OPCODES:
        _run_binop(op, stack)
    elif op == "NEG":
        stack.append(apply_neg(stack.pop()))
    elif op == "NOT":
        stack.append(apply_not(stack.pop()))
    elif op == "JUMP":
        return instr.arg
    elif op == "JUMP_IF_FALSE":
        cond = stack.pop()
        if not _is_bool(cond):
            raise VMRuntimeError("condition must be a bool")
        if not cond:
            return instr.arg
    elif op == "PRINT":
        ctx["output"].append(render(stack.pop()))
    elif op == "POP":
        stack.pop()
    return ip + 1


def execute(program: "Program", *, step_limit: int = 100_000) -> list[str]:
    if not isinstance(step_limit, int) or isinstance(step_limit, bool) or step_limit <= 0:
        raise ValueError("step_limit must be a positive int")
    ctx = {
        "stack": [],
        "vars": [_UNSET] * len(program.names),
        "constants": program.constants,
        "names": program.names,
        "output": [],
    }
    instrs = program.instructions
    ip = 0
    steps = 0
    while True:
        instr = instrs[ip]
        steps += 1
        if steps > step_limit:
            raise StepLimitError("step limit exceeded")
        if instr.op == "HALT":
            break
        ip = _exec_instr(instr, ip, ctx)
    return ctx["output"]

"""Constant folding over the AST. Never changes observable behaviour."""

from .errors import VMRuntimeError
from .parser import (
    AssignStmt,
    BinOp,
    BoolLit,
    FloatLit,
    IfStmt,
    IntLit,
    LetStmt,
    LogicOp,
    Module,
    Neg,
    NotOp,
    PrintStmt,
    StrLit,
    VarRef,
    WhileStmt,
)
from .vm import apply_binary, apply_neg, apply_not

_LITERAL_TYPES = (IntLit, FloatLit, StrLit, BoolLit)


def _literal_value(node: object) -> tuple[bool, object]:
    if isinstance(node, _LITERAL_TYPES):
        return True, node.value
    return False, None


def _wrap_literal(value: object) -> object:
    if type(value) is bool:
        return BoolLit(value)
    if isinstance(value, int):
        return IntLit(value)
    if isinstance(value, float):
        return FloatLit(value)
    return StrLit(value)


def _fold_neg(node: Neg) -> object:
    expr = fold_constants(node.expr)
    is_lit, value = _literal_value(expr)
    if is_lit:
        try:
            return _wrap_literal(apply_neg(value))
        except VMRuntimeError:
            pass
    return Neg(expr)


def _fold_not(node: NotOp) -> object:
    expr = fold_constants(node.expr)
    is_lit, value = _literal_value(expr)
    if is_lit:
        try:
            return _wrap_literal(apply_not(value))
        except VMRuntimeError:
            pass
    return NotOp(expr)


def _fold_binop(node: BinOp) -> object:
    left = fold_constants(node.left)
    right = fold_constants(node.right)
    lok, lval = _literal_value(left)
    rok, rval = _literal_value(right)
    if lok and rok:
        try:
            return _wrap_literal(apply_binary(node.op, lval, rval))
        except VMRuntimeError:
            pass
    return BinOp(node.op, left, right, node.offset)


def _fold_logic(node: LogicOp) -> object:
    left = fold_constants(node.left)
    right = fold_constants(node.right)
    lok, lval = _literal_value(left)
    if lok and type(lval) is bool:
        if node.op == "and" and lval is False:
            return BoolLit(False)
        if node.op == "or" and lval is True:
            return BoolLit(True)
        rok, rval = _literal_value(right)
        if rok and type(rval) is bool:
            return BoolLit(lval and rval if node.op == "and" else lval or rval)
    return LogicOp(node.op, left, right)


def fold_constants(node: object) -> object:
    if isinstance(node, Module):
        return Module([fold_constants(s) for s in node.body])
    if isinstance(node, LetStmt):
        return LetStmt(node.name, fold_constants(node.expr), node.offset)
    if isinstance(node, AssignStmt):
        return AssignStmt(node.name, fold_constants(node.expr), node.offset)
    if isinstance(node, PrintStmt):
        return PrintStmt(fold_constants(node.expr))
    if isinstance(node, IfStmt):
        else_body = None if node.else_body is None else [fold_constants(s) for s in node.else_body]
        return IfStmt(
            fold_constants(node.cond),
            [fold_constants(s) for s in node.then_body],
            else_body,
        )
    if isinstance(node, WhileStmt):
        return WhileStmt(fold_constants(node.cond), [fold_constants(s) for s in node.body])
    if isinstance(node, Neg):
        return _fold_neg(node)
    if isinstance(node, NotOp):
        return _fold_not(node)
    if isinstance(node, BinOp):
        return _fold_binop(node)
    if isinstance(node, LogicOp):
        return _fold_logic(node)
    if isinstance(node, (_LITERAL_TYPES, VarRef)):
        return node
    return node

"""Binary serializer/deserializer for compiled Programs."""

import struct
import zlib

from .compiler import Instr, Program
from .errors import SerializationError
from .opcodes import OPCODE_NUMBERS, OPCODES, OPCODES_WITH_ARG

MAGIC = b"MVM1"
VERSION = 1

_OPCODE_BY_NUMBER: dict[int, str] = {v: k for k, v in OPCODE_NUMBERS.items()}

_TAG_INT = 0x01
_TAG_FLOAT = 0x02
_TAG_STRING = 0x03
_TAG_BOOL = 0x04

_NO_ARG = 0xFFFFFFFF
_I64_MIN = -(2 ** 63)
_I64_MAX = 2 ** 63 - 1


def _encode_const(value: object) -> bytes:
    if type(value) is bool:
        return bytes([_TAG_BOOL, 1 if value else 0])
    if isinstance(value, int):
        if not (_I64_MIN <= value <= _I64_MAX):
            raise SerializationError("integer constant out of signed 64-bit range")
        return bytes([_TAG_INT]) + struct.pack(">q", value)
    if isinstance(value, float):
        return bytes([_TAG_FLOAT]) + struct.pack(">d", value)
    encoded = value.encode("utf-8")
    return bytes([_TAG_STRING]) + struct.pack(">I", len(encoded)) + encoded


def _encode_instr(instr: Instr) -> bytes:
    opcode_num = OPCODE_NUMBERS[instr.op]
    if instr.op in OPCODES_WITH_ARG:
        arg = instr.arg
    else:
        arg = _NO_ARG
    return bytes([opcode_num]) + struct.pack(">I", arg)


def dumps(program: Program) -> bytes:
    parts = [bytes([VERSION])]
    parts.append(struct.pack(">H", len(program.names)))
    for name in program.names:
        encoded = name.encode("utf-8")
        parts.append(struct.pack(">H", len(encoded)) + encoded)
    parts.append(struct.pack(">H", len(program.constants)))
    for const in program.constants:
        parts.append(_encode_const(const))
    parts.append(struct.pack(">I", len(program.instructions)))
    for instr in program.instructions:
        parts.append(_encode_instr(instr))
    body = b"".join(parts)
    checksum = zlib.crc32(body)
    return MAGIC + body + struct.pack(">I", checksum)


class _Reader:
    def __init__(self, data: bytes) -> None:
        self.data = data
        self.pos = 0

    def read(self, n: int) -> bytes:
        if self.pos + n > len(self.data):
            raise SerializationError("truncated data")
        chunk = self.data[self.pos:self.pos + n]
        self.pos += n
        return chunk

    def u8(self) -> int:
        return self.read(1)[0]

    def u16(self) -> int:
        return struct.unpack(">H", self.read(2))[0]

    def u32(self) -> int:
        return struct.unpack(">I", self.read(4))[0]

    def i64(self) -> int:
        return struct.unpack(">q", self.read(8))[0]

    def f64(self) -> float:
        return struct.unpack(">d", self.read(8))[0]


def _read_names(r: _Reader) -> list[str]:
    count = r.u16()
    names = []
    for _ in range(count):
        length = r.u16()
        names.append(r.read(length).decode("utf-8"))
    return names


def _read_one_const(r: _Reader) -> object:
    tag = r.u8()
    if tag == _TAG_INT:
        return r.i64()
    if tag == _TAG_FLOAT:
        return r.f64()
    if tag == _TAG_STRING:
        length = r.u32()
        return r.read(length).decode("utf-8")
    if tag == _TAG_BOOL:
        value = r.u8()
        if value not in (0, 1):
            raise SerializationError("invalid bool payload")
        return value == 1
    raise SerializationError(f"unknown constant tag {tag}")


def _read_constants(r: _Reader) -> list:
    count = r.u16()
    return [_read_one_const(r) for _ in range(count)]


def _read_one_instr(r: _Reader) -> Instr:
    opcode_num = r.u8()
    if opcode_num not in _OPCODE_BY_NUMBER:
        raise SerializationError(f"unknown opcode number {opcode_num}")
    op = _OPCODE_BY_NUMBER[opcode_num]
    raw_arg = r.u32()
    has_arg = op in OPCODES_WITH_ARG
    if has_arg and raw_arg == _NO_ARG:
        raise SerializationError(f"opcode {op} requires an argument")
    if not has_arg and raw_arg != _NO_ARG:
        raise SerializationError(f"opcode {op} takes no argument")
    return Instr(op, raw_arg if has_arg else None)


def _read_instructions(r: _Reader) -> list:
    count = r.u32()
    return [_read_one_instr(r) for _ in range(count)]


def loads(data: bytes) -> Program:
    if len(data) < len(MAGIC) + 1 + 4:
        raise SerializationError("truncated data")
    if data[:len(MAGIC)] != MAGIC:
        raise SerializationError("bad magic")
    body = data[len(MAGIC):-4]
    checksum = struct.unpack(">I", data[-4:])[0]
    if zlib.crc32(body) != checksum:
        raise SerializationError("checksum mismatch")
    r = _Reader(body)
    version = r.u8()
    if version != VERSION:
        raise SerializationError(f"unsupported version {version}")
    names = _read_names(r)
    constants = _read_constants(r)
    instructions = _read_instructions(r)
    if r.pos != len(body):
        raise SerializationError("trailing bytes after checksum")
    return Program(constants, names, instructions)

"""Disassembler: Program -> human readable text."""

from .compiler import Program
from .opcodes import OPCODES_WITH_ARG


def _escape_string(value: str) -> str:
    out = []
    for ch in value:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def _render_const(value: object) -> str:
    if type(value) is bool:
        return "true" if value else "false"
    if isinstance(value, str):
        return _escape_string(value)
    return str(value)


def disassemble(program: Program) -> str:
    lines = []
    for index, instr in enumerate(program.instructions):
        line = f"{index:04d} {instr.op}"
        if instr.op in OPCODES_WITH_ARG:
            line += f" {instr.arg}"
        if instr.op == "CONST":
            line += f"  ; {_render_const(program.constants[instr.arg])}"
        lines.append(line)
    return "\n".join(lines) + ("\n" if lines else "")

